const out = [];
const seen = new Set();
const dropQuery = /^(utm_|fbclid$|gclid$|mc_|ref$|source$)/i;
function canonicalise(value) { try { const u = new URL(value); u.hash = ''; for (const key of [...u.searchParams.keys()]) if (dropQuery.test(key)) u.searchParams.delete(key); u.searchParams.sort(); return `${u.origin}${u.pathname.replace(/\/$/, '')}${u.search}`; } catch { return null; } }
for (const item of $input.all()) {
  const payload = item.json || {};
  const rows = Array.isArray(payload.results) ? payload.results : (Array.isArray(payload.jobs) ? payload.jobs : [payload]);
  for (const raw of rows) {
    const route = raw.redirect_url || raw.job_url || raw.url || raw.shareLink || raw.share_link || '';
    const canonicalUrl = canonicalise(route);
    const title = raw.title || raw.job_title || '';
    const company = raw.company?.display_name || raw.companyName || raw.company || '';
    if (!title || !company || !canonicalUrl || /linkedin\.com\/jobs/i.test(route)) continue;
    if (seen.has(canonicalUrl)) continue;
    seen.add(canonicalUrl);
    out.push({ source: raw.source || (raw.jobId ? 'seek_apify' : 'adzuna'), source_record_id: String(raw.id || raw.jobId || canonicalUrl), canonical_url: canonicalUrl, application_route: route, application_route_type: raw.jobId ? 'SEEK search lead' : 'Adzuna listing', listing_verification: 'Confirm the original listing and requirements before applying.', title, company, location: raw.location?.display_name || raw.location || '', description: raw.description || raw.jobContent || raw.job_abstract || '', salary: { min: raw.salary_min ?? null, max: raw.salary_max ?? null, label: raw.salaryLabel || '' }, work_type: raw.contract_type || raw.workType || '', remote: /remote|work from home|hybrid/i.test(`${raw.title || ''} ${raw.description || ''}`), lane: 'core', posted_at: raw.created || raw.listingDate || null, screening_score: null, fit: 'Review', matched_terms: [], evidence: [], gaps: [], requirements_to_confirm: ['Confirm the original employer route, closing date, location, roster, licences, clearances, and work rights.'], confidence: null, needs_human_review: true });
  }
}
return [{ json: { jobs: out } }];
